//! Golden admission, queue-order, head-start and prediction cases from work.py (decision R1-18).
//!
//! Each fixture under tests/fixtures/admission/<n>.json was generated by tests/fixtures/gen_admission.py, which runs
//! work.py's own functions in-process (Supervisor.blocker, waiting_order, head_start_estimate, predict) against a real
//! sqlite database for their SQL, with the clock, host memory and CPU count injected. The expected values are Python's,
//! not hand-derived. Every fixture is replayed through the public `quiet::blocker`, `admit`, and `predict` API, and the
//! cause and reason text, or the numbers, must equal Python's exactly.
//!
//! Mapping rules, so a mismatch can be told apart from a mapping error:
//!   - settings: memory_budget null is Auto, 0 is Off, n is Kib(n); other fields are the same names.
//!   - windows (the tasks with a quiet window, running or ended): window close = min(quiet_until, ended or quiet_until),
//!     which is the SQL `MIN(quiet_until, COALESCE(ended, quiet_until))` of drain_start.
//!   - paused and manual quiet windows are Rust-only additions: they are always empty here.
//!   - predict history: per level, the runs whose signature at that level equals the candidate's, that ran (status
//!     not null and not 126 or 127, started, ended and cpu_time present), newest first by ended.
//!   - floats: inputs are JSON numbers with at most 15 significant digits, which serde_json parses exactly; expected
//!     floats are repr() strings, parsed with str::parse, so no decimal rounding can hide a difference.
//!
//! KNOWN_FAILURES lists fixtures whose Rust result differs from work.py because of a bug in src/. Each one must still
//! mismatch: once it matches, the entry is stale and the test fails until it is removed.

use std::path::{Path, PathBuf};

use agora_sched::admit::{
    Budgets, Cause, MachineSnapshot, MemLevel, RunningJob, Signals, WaitingJob,
    head_start_estimate, waiting_order_cmp,
};
use agora_sched::predict::{History, Level, Run, predict};
use agora_sched::quiet::{self, AdmitInput};
use agora_sched::settings::{MemBudget, MemLimit, WorkSettings};
use serde_json::Value;

/// Fixtures whose Rust result differs from work.py: (file name, the bug, expected vs actual). Empty while every
/// fixture matches.
const KNOWN_FAILURES: &[(&str, &str)] = &[];

/// Fixture counts per kind, as the generator writes them: a deleted fixture must fail the test.
const BLOCKER_COUNT: usize = 80;
const ORDER_COUNT: usize = 8;
const HEAD_COUNT: usize = 8;
const PREDICT_COUNT: usize = 24;

fn fixture_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/admission")
}

/// Every fixture of one kind, in file-name order, with its file name.
fn fixtures_of(kind: &str) -> Vec<(String, Value)> {
    let mut paths: Vec<PathBuf> = std::fs::read_dir(fixture_dir())
        .expect("the admission fixture directory is readable")
        .map(|entry| entry.expect("directory entry").path())
        .filter(|path| path.extension().is_some_and(|ext| ext == "json"))
        .collect();
    paths.sort();
    paths
        .into_iter()
        .filter_map(|path| {
            let text = std::fs::read_to_string(&path).expect("fixture is readable");
            let case: Value = serde_json::from_str(&text).expect("fixture is JSON");
            (case["kind"] == kind).then(|| {
                let file = path
                    .file_name()
                    .expect("file name")
                    .to_string_lossy()
                    .into_owned();
                (file, case)
            })
        })
        .collect()
}

/// Replays every fixture of `kind` through `check`, which returns Err(mismatch) for a difference. Unlisted mismatches
/// and stale known failures fail the test; every mismatch is printed.
fn replay(kind: &str, expected_count: usize, check: impl Fn(&Value) -> Result<(), String>) {
    let cases = fixtures_of(kind);
    assert_eq!(cases.len(), expected_count, "the {kind} fixture count");
    let mut mismatches = Vec::new();
    let mut unexpected = Vec::new();
    let mut stale = Vec::new();
    for (file, case) in &cases {
        let name = case["name"].as_str().unwrap_or_default();
        let known = KNOWN_FAILURES
            .iter()
            .find(|(known, _)| *known == file.as_str());
        match (check(case), known) {
            (Err(detail), Some((_, bug))) => {
                mismatches.push(format!("known {file} ({name}): {detail} [{bug}]"))
            }
            (Err(detail), None) => {
                mismatches.push(format!("{file} ({name}): {detail}"));
                unexpected.push(format!("{file} ({name})"));
            }
            (Ok(()), Some((_, bug))) => stale.push(format!(
                "{file} ({name}) now matches; drop it from KNOWN_FAILURES: {bug}"
            )),
            (Ok(()), None) => {}
        }
    }
    for line in &mismatches {
        eprintln!("MISMATCH {line}");
    }
    assert!(
        unexpected.is_empty() && stale.is_empty(),
        "{} of {} {kind} fixtures mismatch work.py ({} unexpected, {} stale known)\n{}\n{}",
        mismatches.len(),
        cases.len(),
        unexpected.len(),
        stale.len(),
        mismatches.join("\n"),
        stale.join("\n"),
    );
}

fn num(value: &Value) -> f64 {
    value.as_f64().expect("a JSON number")
}

fn opt_num(value: &Value) -> Option<f64> {
    (!value.is_null()).then(|| num(value))
}

/// An expected float: the repr() text work.py printed.
fn expected_float(value: &Value) -> f64 {
    value
        .as_str()
        .expect("an expected float is text")
        .parse()
        .expect("a float repr")
}

fn text(value: &Value) -> String {
    value.as_str().expect("a string").to_owned()
}

fn cause_name(cause: Cause) -> &'static str {
    match cause {
        Cause::Cores => "cores",
        Cause::Capacity => "capacity",
        Cause::Reserved => "reserved",
        Cause::Memory => "memory",
        Cause::Idle => "idle",
        Cause::Load => "load",
        Cause::Quiet => "quiet",
        Cause::Ahead => "ahead",
        Cause::Paused => "paused",
    }
}

fn settings_of(case: &Value) -> WorkSettings {
    let s = &case["settings"];
    let memory_budget = match &s["memory_budget"] {
        Value::Null => MemBudget::Auto,
        other if other.as_u64() == Some(0) => MemBudget::Off,
        other => MemBudget::Kib(other.as_u64().expect("memory_budget is null, 0 or KiB")),
    };
    let memory_limit = match s["memory_limit"].as_str().expect("memory_limit") {
        "warning" => MemLimit::Warning,
        "critical" => MemLimit::Critical,
        "off" => MemLimit::Off,
        other => panic!("unknown memory_limit {other}"),
    };
    WorkSettings {
        cpu_budget: opt_num(&s["cpu_budget"]),
        capacity: opt_num(&s["capacity"]),
        memory_budget,
        idle_min: num(&s["idle_min"]),
        memory_limit,
        load_factor: num(&s["load_factor"]),
        load_wait: num(&s["load_wait"]),
        backfill_wait: num(&s["backfill_wait"]),
        small_weight: num(&s["small_weight"]),
        aging: num(&s["aging"]),
        quiet_drain: num(&s["quiet_drain"]),
        quiet_max: num(&s["quiet_max"]),
        ..WorkSettings::default()
    }
}

fn machine_of(case: &Value) -> MachineSnapshot {
    let sig = &case["signals"];
    let signals = (!sig.is_null()).then(|| Signals {
        idle_pct: opt_num(&sig["idle_pct"]),
        memory_level: sig["memory_level"].as_str().map(|level| match level {
            "normal" => MemLevel::Normal,
            "warning" => MemLevel::Warning,
            "critical" => MemLevel::Critical,
            other => panic!("unknown memory level {other}"),
        }),
        load1: opt_num(&sig["load1"]),
        load_gate: sig["load_gate"].as_bool().expect("load_gate"),
        memory_used_kib: sig["memory_used_kib"].as_u64(),
    });
    MachineSnapshot {
        cpus: num(&case["cpus"]),
        total_memory_kib: case["total_memory_kib"].as_u64(),
        disk_free_kib: None,
        signals,
    }
}

fn running_of(rows: &Value) -> Vec<RunningJob> {
    rows.as_array()
        .expect("running is an array")
        .iter()
        .map(|row| RunningJob {
            id: text(&row["id"]),
            weight: num(&row["weight"]),
            pred_cores: opt_num(&row["pred_cores"]),
            pred_rss_p90_kib: row["pred_rss_p90"].as_u64(),
            pred_duration_p90_s: opt_num(&row["pred_duration_p90"]),
            rss_kib: row["rss"].as_u64(),
            started_s: opt_num(&row["started"]),
            quiet_until_s: opt_num(&row["quiet_until"]),
        })
        .collect()
}

fn waiting_of(rows: &Value) -> Vec<WaitingJob> {
    rows.as_array()
        .expect("waiting is an array")
        .iter()
        .map(|row| WaitingJob {
            id: text(&row["id"]),
            kind: text(&row["kind"]),
            seq: row["seq"].as_i64().expect("seq"),
            requested_s: num(&row["requested"]),
            weight: num(&row["weight"]),
            pred_cores: opt_num(&row["pred_cores"]),
            pred_duration_s: opt_num(&row["pred_duration"]),
            pred_duration_p90_s: opt_num(&row["pred_duration_p90"]),
            pred_rss_p90_kib: row["pred_rss_p90"].as_u64(),
            machine_held_since_s: None,
        })
        .collect()
}

/// The decision for the candidate, as (cause, reason), or None when it may start.
fn blocker_result(case: &Value) -> Option<(String, String)> {
    let running = running_of(&case["running"]);
    let waiting = waiting_of(&case["waiting"]);
    let candidate = text(&case["candidate"]);
    let job = waiting
        .iter()
        .find(|item| item.id == candidate)
        .expect("the candidate is in the line")
        .clone();
    let window_closes = case["windows"]
        .as_array()
        .expect("windows is an array")
        .iter()
        .filter_map(|row| {
            let until = opt_num(&row["quiet_until"])?;
            let close = opt_num(&row["ended"]).map_or(until, |ended| ended.min(until));
            Some((text(&row["id"]), close))
        })
        .collect();
    let input = AdmitInput {
        now_s: num(&case["now"]),
        settings: settings_of(case),
        machine: machine_of(case),
        running,
        waiting,
        window_closes,
        paused: None,
        manual_quiet: Vec::new(),
    };
    quiet::blocker(&job, &input, &input.running, &input.waiting)
        .map(|hold| (cause_name(hold.cause).to_owned(), hold.reason))
}

fn check_blocker(case: &Value) -> Result<(), String> {
    let expected = match &case["expected"] {
        Value::Null => None,
        found => Some((text(&found["cause"]), text(&found["reason"]))),
    };
    let actual = blocker_result(case);
    if expected == actual {
        Ok(())
    } else {
        Err(format!("expected {expected:?}, got {actual:?}"))
    }
}

fn check_order(case: &Value) -> Result<(), String> {
    let aging = num(&case["aging"]);
    let mut rows = waiting_of(&case["waiting"]);
    rows.sort_by(|a, b| waiting_order_cmp(a, b, aging));
    let actual: Vec<String> = rows.into_iter().map(|row| row.id).collect();
    let expected: Vec<String> = case["expected_order"]
        .as_array()
        .expect("expected_order is an array")
        .iter()
        .map(text)
        .collect();
    if expected == actual {
        Ok(())
    } else {
        Err(format!("expected order {expected:?}, got {actual:?}"))
    }
}

fn check_head_start(case: &Value) -> Result<(), String> {
    let cpus = num(&case["cpus"]);
    let budgets = Budgets {
        cpus,
        budget: opt_num(&case["cpu_budget"]).unwrap_or(cpus),
        capacity: None,
        memory_budget_kib: None,
        load_limit: cpus * 1.5,
    };
    let actual = head_start_estimate(
        num(&case["head_need"]),
        &running_of(&case["running"]),
        &budgets,
        num(&case["now"]),
    );
    let expected = expected_float(&case["expected"]);
    if actual == expected {
        Ok(())
    } else {
        Err(format!("expected start {expected:?}, got {actual:?}"))
    }
}

/// Whether a run counts toward a prediction: work.py's RAN filter.
fn ran(row: &Value) -> bool {
    let status = &row["status"];
    !status.is_null()
        && !matches!(status.as_i64(), Some(126 | 127))
        && !row["started"].is_null()
        && !row["ended"].is_null()
        && !row["cpu_time"].is_null()
}

/// Ran rows, newest first by end time (the SQL's ORDER BY ended DESC).
fn newest_first<'a>(rows: impl Iterator<Item = &'a Value>) -> Vec<&'a Value> {
    let mut rows: Vec<&Value> = rows.collect();
    rows.sort_by(|a, b| num(&b["ended"]).total_cmp(&num(&a["ended"])));
    rows
}

fn run_of(row: &Value) -> Run {
    Run {
        started_ms: (num(&row["started"]) * 1000.0) as i64,
        ended_ms: (num(&row["ended"]) * 1000.0) as i64,
        cpu_seconds: num(&row["cpu_time"]),
        rss_peak_kib: row["rss_peak"].as_u64(),
    }
}

/// The history work.py's queries return for this candidate, in the shape `predict` takes.
fn history_of(case: &Value) -> History {
    let runs = case["runs"].as_array().expect("runs is an array");
    let cpus = num(&case["cpus"]);
    let levels = ["full", "head", "prog", "tool"];
    let mut by_level: [Vec<Run>; 4] = Default::default();
    for (slot, level) in levels.iter().enumerate() {
        let Some(key) = case["signed"][level].as_str() else {
            continue;
        };
        let column = format!("sig_{level}");
        let matching = runs
            .iter()
            .filter(|row| ran(row) && row[column.as_str()].as_str() == Some(key));
        by_level[slot] = newest_first(matching).into_iter().map(run_of).collect();
    }
    let ran_rows = || runs.iter().filter(|row| ran(row));
    let exclusive_runs = newest_first(ran_rows().filter(|row| num(&row["weight"]) >= cpus))
        .into_iter()
        .map(run_of)
        .collect();
    let recent_durations_s = newest_first(ran_rows())
        .into_iter()
        .map(|row| num(&row["ended"]) - num(&row["started"]))
        .collect();
    History {
        by_level,
        recent_durations_s,
        exclusive_runs,
    }
}

fn level_name(level: Level) -> &'static str {
    match level {
        Level::Full => "full",
        Level::Head => "head",
        Level::Prog => "prog",
        Level::Tool => "tool",
        Level::Exclusive => "exclusive",
        Level::None => "none",
    }
}

/// (cores, rss, rss p90, duration, duration p90, level, runs, basis) of a prediction.
type Predicted = (
    f64,
    Option<u64>,
    Option<u64>,
    f64,
    Option<f64>,
    &'static str,
    u32,
    String,
);

fn check_predict(case: &Value) -> Result<(), String> {
    let e = &case["expected"];
    let expected: Predicted = (
        expected_float(&e["cores"]),
        e["rss_kib"].as_u64(),
        e["rss_p90_kib"].as_u64(),
        expected_float(&e["duration"]),
        e["duration_p90"]
            .as_str()
            .map(|text| text.parse().expect("a float repr")),
        match e["level"].as_str().expect("level") {
            "full" => "full",
            "head" => "head",
            "prog" => "prog",
            "tool" => "tool",
            "exclusive" => "exclusive",
            "none" => "none",
            other => panic!("unknown level {other}"),
        },
        u32::try_from(e["runs"].as_u64().expect("runs")).expect("runs fits u32"),
        text(&e["basis"]),
    );
    let p = predict(&history_of(case), num(&case["weight"]), num(&case["cpus"]));
    let actual: Predicted = (
        p.cores,
        p.rss_kib,
        p.rss_p90_kib,
        p.duration_s,
        p.duration_p90_s,
        level_name(p.level),
        p.runs,
        p.basis(),
    );
    if expected == actual {
        Ok(())
    } else {
        Err(format!("expected {expected:?}, got {actual:?}"))
    }
}

#[test]
fn blocker_decisions_match_work_py_supervisor_blocker() {
    replay("blocker", BLOCKER_COUNT, check_blocker);
}

#[test]
fn queue_order_matches_work_py_waiting_order() {
    replay("order", ORDER_COUNT, check_order);
}

#[test]
fn head_start_matches_work_py_head_start_estimate() {
    replay("head_start", HEAD_COUNT, check_head_start);
}

#[test]
fn predictions_match_work_py_predict() {
    replay("predict", PREDICT_COUNT, check_predict);
}
